<AuthorizeView Roles="Editor">
    <Authorized>
        <p>Welcome to the Editor page, @context.User.Identity?.Name!</p>
    </Authorized>
    <NotAuthorized>
        <p>Access denied. You must have the "Editor" role to view this page.</p>
